SELECT id, title, doc_type, status, chunk_count, version, error_msg, create_time FROM kb_document WHERE deleted = 0
AND title LIKE CONCAT('%', #{keyword}, '%')
AND doc_type = #{docType}
AND status = #{status}
ORDER BY id DESC

mapper.update:
UPDATE kb_document
SET status = #{status},
    chunk_count = COALESCE(#{chunkCount}, chunk_count),
    error_msg = #{errorMsg}
WHERE id = #{id}
